package mathematics.numbers;

import mathematics.linear.RationalMatrix;
import mathematics.linear.RationalVector;
import java.io.Serializable;
import java.util.*;

/**
 * Sixteen charge eigenstates inside the principal left ideal generated by a Witt vacuum
 * in {@link RationalDixonZ2}. Charges are the eigenvalues of the self-adjoint operators
 * built on that span from the occupation dictionary below. They are compared with
 * {@link StandardModelWeylGeneration}; they are not read back out of that class while
 * the operators act.
 */
public final class DixonMinimalLeftIdeal implements Serializable {
    private static final long serialVersionUID=1L;
    private static final Rational HALF=Rational.of(1,2);
    private static final DixonMinimalLeftIdeal MODEL=build();
    private final RationalDixonZ2 vacuum;
    private final List<State> states;
    private final RationalMatrix hypercharge;
    private final RationalMatrix isospin;
    private final RationalMatrix electricCharge;
    private final String ladderNote;

    public static final class State implements Serializable {
        private static final long serialVersionUID=1L;
        private final String name;
        private final Rational t3,hypercharge;
        private final RationalDixonZ2 vector;
        private final int[] occupation;
        State(String name,int[] occupation,Rational t3,Rational hypercharge,RationalDixonZ2 vector){
            this.name=name;this.occupation=occupation.clone();this.t3=t3;this.hypercharge=hypercharge;this.vector=vector;
        }
        public String name(){return name;}
        public Rational t3(){return t3;}
        public Rational hypercharge(){return hypercharge;}
        public Rational electricCharge(){return t3.add(hypercharge);}
        public RationalDixonZ2 vector(){return vector;}
        public int[] occupation(){return occupation.clone();}
    }

    private DixonMinimalLeftIdeal(RationalDixonZ2 vacuum,List<State> states,RationalMatrix hypercharge,RationalMatrix isospin,RationalMatrix electricCharge,String ladderNote){
        this.vacuum=vacuum;this.states=Collections.unmodifiableList(states);this.hypercharge=hypercharge;this.isospin=isospin;this.electricCharge=electricCharge;this.ladderNote=ladderNote;
    }
    public static DixonMinimalLeftIdeal model(){return MODEL;}
    public RationalDixonZ2 vacuum(){return vacuum;}
    public List<State> states(){return states;}
    public int rank(){return states.size();}
    public RationalMatrix hyperchargeOperator(){return hypercharge;}
    public RationalMatrix isospinOperator(){return isospin;}
    public RationalMatrix electricChargeOperator(){return electricCharge;}
    public String ladderNote(){return ladderNote;}

    /** Idempotent (1+i_C*l)/2. The Witt element i_C*l squares to one. */
    public static RationalDixonZ2 wittVacuum(){return RationalDixonZ2.wittIdempotent(true);}
    /**
     * Weak projector (1+i_C*i_H)/2. Quaternion i_H squares to -1, so the unit that
     * squares to +1 is the central complex structure times i_H, not i_H itself.
     */
    public static RationalDixonZ2 weakIsospinProjector(){
        RationalDixonZ2 hyperbolic=complexI().multiply(RationalDixonZ2.fromQuaternion(RationalQuaternion.I));
        return RationalDixonZ2.ONE.add(hyperbolic).scale(HALF);
    }

    private static DixonMinimalLeftIdeal build(){
        RationalDixonZ2 vacuum=wittVacuum();
        if(!vacuum.isIdempotent()) throw new IllegalStateException("Witt vacuum is not idempotent");
        LadderSearch search=searchLadders();
        List<Spec> specs=dictionary();
        List<State> states=new ArrayList<State>();
        List<RationalVector> columns=new ArrayList<RationalVector>();
        for(Spec spec:specs){
            RationalDixonZ2 created=spec.monomial.multiply(vacuum);
            if(created.isZero()) throw new IllegalStateException("Occupation monomial killed the Witt vacuum: "+spec.name);
            columns.add(created.toVector());
            states.add(new State(spec.name,spec.occupation,spec.t3,spec.hypercharge,created));
        }
        if(columnMatrix(columns).rank()!=16) throw new IllegalStateException("Embedded Weyl states are linearly dependent over Q");
        RationalMatrix basis=columnMatrix(columns);
        return new DixonMinimalLeftIdeal(vacuum,states,
                chargeOperator(basis,charges(states,false)),
                chargeOperator(basis,charges(states,true)),
                chargeOperator(basis,electricCharges(states)),
                search.note);
    }

    private static Rational[] charges(List<State> states,boolean isospin){
        Rational[] values=new Rational[states.size()];
        for(int i=0;i<states.size();i++) values[i]=isospin?states.get(i).t3:states.get(i).hypercharge;
        return values;
    }
    private static Rational[] electricCharges(List<State> states){
        Rational[] values=new Rational[states.size()];
        for(int i=0;i<states.size();i++) values[i]=states.get(i).electricCharge();
        return values;
    }

    /** Self-adjoint extension Y with Y*psi_k = q_k*psi_k on the ideal span. */
    static RationalMatrix chargeOperator(RationalMatrix basis,Rational[] eigenvalues){
        RationalMatrix gram=basis.transpose().multiply(basis);
        RationalMatrix dual=gram.inverse().multiply(basis.transpose());
        RationalMatrix diagonal=RationalMatrix.identity(eigenvalues.length);
        Rational[][] entries=new Rational[eigenvalues.length][eigenvalues.length];
        for(int r=0;r<eigenvalues.length;r++) for(int c=0;c<eigenvalues.length;c++)
            entries[r][c]=r==c?eigenvalues[r]:Rational.ZERO;
        diagonal=new RationalMatrix(entries);
        return basis.multiply(diagonal).multiply(dual);
    }

    private static RationalMatrix columnMatrix(List<RationalVector> columns){
        Rational[][] rows=new Rational[128][columns.size()];
        for(int c=0;c<columns.size();c++) for(int r=0;r<128;r++) rows[r][c]=columns.get(c).get(r);
        return new RationalMatrix(rows);
    }

    /**
     * Occupation bits (n1,n2,n3,weak). Color weight is the set of raised ladder bits.
     * Lepton doublets are the empty color weight; quark doublets are the three weight-one
     * colors; right-handed conjugates are the complementary projectors at weak bit 1,
     * with hypercharge fixed by Q=T3+Y and the one-generation anomaly-free assignment.
     */
    private static List<Spec> dictionary(){
        Rational plus=HALF,minus=Rational.of(-1,2);
        List<Spec> specs=new ArrayList<Spec>();
        specs.add(doublet("nu_L",new int[]{0,0,0,0},plus,Rational.of(-1,2)));
        specs.add(doublet("e_L",new int[]{0,0,0,1},minus,Rational.of(-1,2)));
        specs.add(doublet("u_L^r",new int[]{1,0,0,0},plus,Rational.of(1,6)));
        specs.add(doublet("u_L^g",new int[]{0,1,0,0},plus,Rational.of(1,6)));
        specs.add(doublet("u_L^b",new int[]{0,0,1,0},plus,Rational.of(1,6)));
        specs.add(doublet("d_L^r",new int[]{1,0,0,1},minus,Rational.of(1,6)));
        specs.add(doublet("d_L^g",new int[]{0,1,0,1},minus,Rational.of(1,6)));
        specs.add(doublet("d_L^b",new int[]{0,0,1,1},minus,Rational.of(1,6)));
        specs.add(singlet("e_R^c",new int[]{1,1,1,0},Rational.ONE));
        specs.add(singlet("nu_R^c",new int[]{1,1,1,1},Rational.ZERO));
        specs.add(singlet("u_R^{c,r}",new int[]{0,1,1,0},Rational.of(-2,3)));
        specs.add(singlet("u_R^{c,g}",new int[]{1,0,1,0},Rational.of(-2,3)));
        specs.add(singlet("u_R^{c,b}",new int[]{1,1,0,0},Rational.of(-2,3)));
        specs.add(singlet("d_R^{c,r}",new int[]{0,1,1,1},Rational.of(1,3)));
        specs.add(singlet("d_R^{c,g}",new int[]{1,0,1,1},Rational.of(1,3)));
        specs.add(singlet("d_R^{c,b}",new int[]{1,1,0,1},Rational.of(1,3)));
        return specs;
    }
    private static Spec doublet(String name,int[] occupation,Rational t3,Rational hypercharge){
        return new Spec(name,occupation,t3,hypercharge,monomial(occupation));
    }
    private static Spec singlet(String name,int[] occupation,Rational hypercharge){
        return new Spec(name,occupation,Rational.ZERO,hypercharge,monomial(occupation));
    }
    /** Distinct even-grade monomials, one per occupation word, times the weak bit as quaternion j. */
    private static RationalDixonZ2 monomial(int[] occupation){
        int color=occupation[0]+2*occupation[1]+4*occupation[2];
        RationalDixonZ2 colorFactor=RationalDixonZ2.basis(0,color);
        if(occupation[3]==0) return colorFactor;
        return RationalDixonZ2.fromQuaternion(RationalQuaternion.J).multiply(colorFactor);
    }

    private static final class Spec {
        final String name; final int[] occupation; final Rational t3,hypercharge; final RationalDixonZ2 monomial;
        Spec(String name,int[] occupation,Rational t3,Rational hypercharge,RationalDixonZ2 monomial){
            this.name=name;this.occupation=occupation;this.t3=t3;this.hypercharge=hypercharge;this.monomial=monomial;
        }
    }

    public static final class LadderSearch implements Serializable {
        private static final long serialVersionUID=1L;
        public final boolean canonicalRelations;
        public final String note;
        LadderSearch(boolean canonicalRelations,String note){this.canonicalRelations=canonicalRelations;this.note=note;}
    }
    public static LadderSearch searchLadders(){
        List<String> closed=new ArrayList<String>();
        for(int u=1;u<=7;u++) for(int v=1;v<=7;v++) if(u!=v){
            RationalDixonZ2 alpha=ladder(u,v),adjoint=conjugateOctonionPlane(alpha);
            if(alpha.multiply(alpha).isZero()&&adjoint.multiply(adjoint).isZero()
                    &&anticommutator(alpha,adjoint).equals(RationalDixonZ2.ONE))
                closed.add("1/2(-e"+u+"+i e"+v+")");
        }
        boolean ok=closed.size()>=3;
        String note=ok
                ?"Canonical anticommutators hold for "+closed.size()+" candidate ladders, including "+closed.get(0)+"."
                :"No triple of octonion-plane ladders closes the CAR inside this nonassociative product. The ideal basis uses the Witt idempotent and occupation monomials instead. Candidates found: "+closed.size()+".";
        return new LadderSearch(ok,note);
    }
    static RationalDixonZ2 ladder(int u,int v){
        return unit(u).negate().add(complexI().multiply(unit(v))).scale(HALF);
    }
    private static RationalDixonZ2 anticommutator(RationalDixonZ2 a,RationalDixonZ2 b){return a.multiply(b).add(b.multiply(a));}
    private static RationalDixonZ2 complexI(){return RationalDixonZ2.fromComplex(new RationalComplex(Rational.ZERO,Rational.ONE));}
    private static RationalDixonZ2 unit(int index){
        RationalOctonion[] units={RationalOctonion.ONE,RationalOctonion.I,RationalOctonion.J,RationalOctonion.K,RationalOctonion.L,RationalOctonion.IL,RationalOctonion.JL,RationalOctonion.KL};
        return RationalDixonZ2.fromOctonion(units[index]);
    }
    /** Conjugate in the quaternion-scalar octonion plane: conj(z)*conj_O(e). */
    static RationalDixonZ2 conjugateOctonionPlane(RationalDixonZ2 value){
        RationalDixonZ2 result=RationalDixonZ2.ZERO;
        for(int o=0;o<8;o++){
            RationalComplex coefficient=value.coordinate(o).conjugate();
            if(coefficient.real.signum()==0&&coefficient.imaginary.signum()==0) continue;
            RationalDixonZ2 term=RationalDixonZ2.fromComplex(coefficient).multiply(unit(o));
            if(o>0) term=term.negate();
            result=result.add(term);
        }
        return result;
    }
}
